INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (98,'Applanation tonometry shows elevated bilateral IOP. Central corneal thickness OD 545um, OS 550um. Cup-to-disc ratio 0.4. Visual field Humphrey 24-2 ordered.','Primary Open-Angle Glaucoma Suspect (IOP 23 mmHg OD, 24 mmHg OS)',61,12);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (99,'Severe itching, cobblestone papillae noted on superior tarsal conjunctiva. Minimal mucoid discharge. Cornea clear without epitheliopathy.','Seasonal Allergic Conjunctivitis with Papillary Reaction',61,13);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (100,'Glare while night driving. BCVA OD 6/12, OS 6/6. Biometry and IOL power calculation performed. Patient scheduled for elective Phacoemulsification with Monofocal IOL.','Nuclear Sclerotic Cataract Grade 2 (Right Eye)',61,14);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (101,'Eyelid margin erythema, capped meibomian orifices, tear breakup time reduced to 5 seconds. Counseled on warm compresses and eyelid hygiene.','Posterior Blepharitis & Meibomian Gland Dysfunction (MGD)',61,15);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (102,'Superficial punctate keratitis (SPK) over inferior cornea. Discontinue soft hydrogel contacts for 14 days. Re-fit to high Dk/t silicone hydrogel recommended.','Contact Lens-Induced Keratopathy & Hypoxia',61,25);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (103,'Weiss ring noted in right vitreous cavity. 360-degree scleral depression examination confirms flat retina without tears, breaks, or lattice degeneration.','Acute Posterior Vitreous Detachment (PVD) - Right Eye',61,26);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (104,'Tear meniscus height < 0.2mm. Marked corneal fluorescein staining. Temporary collagen punctal plugs placed in lower canaliculi with immediate subjective relief.','Aqueous-Deficient Dry Eye Syndrome (Schirmer I: 4mm OD, 5mm OS)',61,27);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (105,'Patient reports 10 hours screen time daily. Decreased blink rate. Punctate epithelial erosions. Prescribed 20-20-20 rule and anti-reflective blue-blocking lenses.','Digital Eye Strain & Accommodative Fatigue',61,28);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (106,'Discrete, non-tender 4mm nodule in right upper tarsal plate. No acute preseptal cellulitis. Prescribed hot compresses and topical steroid-antibiotic combination.','Chronic Meibomian Cyst (Chalazion) - Right Upper Lid',61,29);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (107,'Axial length measured at 25.1mm OD, 25.0mm OS. Axial elongation rate slowed following low-dose atropine 0.01% therapy. Fundus normal.','Progressive Axial Myopia (OD -4.25, OS -4.00)',61,30);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (108,'Bilateral intermediate drusen seen in macula. No subretinal fluid or hemorrhages on OCT macula. Amsler grid testing negative for metamorphopsia.','Early Age-Related Macular Degeneration (Dry AMD)',61,31);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (109,'Rust ring successfully debrided under topical anesthesia. Fluorescein staining shows 80% re-epithelialization. Anterior chamber quiet, pupil round and reactive.','Superficial Corneal Abrasion (Post-Foreign Body Removal)',61,32);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (110,'Sectoral hyperemia of deep episcleral vessels in superotemporal quadrant. Blanching achieved with 2.5% phenylephrine test. Mild tender discomfort, no scleral edema.','Simple Sectoral Episcleritis (Left Eye)',61,33);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (111,'Distance visual acuity 6/6 uncorrected BE. Difficulty reading fine print in low light. Prescribed progressive addition lenses (PAL) with blue-filtering coating.','Presbyopia (+1.50 DS Near Add BE)',61,34);
INSERT INTO `medical_records` (`id`, `clinical_notes`, `diagnosis`, `doctor_id`, `patient_id`) VALUES (112,'Vascularized triangular fibrovascular growth extending 1.2mm onto clear nasal cornea. Visual axis unobstructed. Advised UV protection sunglasses when outdoors.','Nasal Pterygium Grade 1 (Right Eye)',61,35);
